import { Component } from '@angular/core';
import {
  IconPlus, IconArrowUp, IconUserPlus, IconFileImport,
  IconFileExport, IconMessageCircle, IconHeadset, IconBell,
} from '@tabler/icons-angular';
import { TranslateModule } from '@ngx-translate/core';
import { HrmFloatButton, HrmFloatButtonGroup } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Float Button (Action) — cấu trúc chuẩn: Thêm mới / Nhóm mở rộng / Badge & mô tả.
 *  Nút nổi vốn position:fixed ở góc màn hình thật; ở đây gói trong "khung màn hình" thu nhỏ
 *  (.fb-screen position:relative) + override nz-float-* sang position:absolute để mỗi ví dụ nằm
 *  gọn trong thẻ, không đè lên nhau ở góc trình duyệt. Song ngữ qua i18n docs.floatButton.*. */
@Component({
  selector: 'sg-doc-float-button',
  imports: [TranslateModule, HrmFloatButton, HrmFloatButtonGroup, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Action" [title]="'docs.floatButton.title' | translate" [desc]="'docs.floatButton.desc' | translate">

      <div sgOverview>
        <div class="fb-screen">
          <div class="fb-hint">{{ 'docs.floatButton.cornerHint' | translate }}</div>
          <hrm-float-button type="primary" [icon]="plus" [description]="'docs.floatButton.add' | translate" />
        </div>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.floatButton.purpose' | translate"
          [when]="when"
          [behavior]="'docs.floatButton.behavior' | translate"
          [avoid]="'docs.floatButton.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do><span [innerHTML]="'docs.floatButton.do1' | translate"></span></sg-do>
        <sg-do><span [innerHTML]="'docs.floatButton.do2' | translate"></span></sg-do>
        <sg-do><span [innerHTML]="'docs.floatButton.do3' | translate"></span></sg-do>
        <sg-dont><span [innerHTML]="'docs.floatButton.dont1' | translate"></span></sg-dont>
      </div>

      <div sgExamples>

        <sg-example [title]="'docs.floatButton.exAddT' | translate"
          [desc]="'docs.floatButton.exAddD' | translate">
          <sg-row [label]="'docs.floatButton.rowAdd' | translate">
            <div class="fb-screen">
              <hrm-float-button type="primary" [icon]="plus" [description]="'docs.floatButton.addEmployee' | translate" />
            </div>
            <div class="fb-screen">
              <hrm-float-button [icon]="arrowUp" [description]="'docs.floatButton.toTop' | translate" />
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.floatButton.exGroupT' | translate"
          [desc]="'docs.floatButton.exGroupD' | translate">
          <sg-row [label]="'docs.floatButton.rowGroup' | translate">
            <div class="fb-screen fb-screen-tall">
              <hrm-float-button-group [icon]="plus" type="primary" trigger="click">
                <hrm-float-button [icon]="userPlus" [description]="'docs.floatButton.add' | translate" />
                <hrm-float-button [icon]="fileImport" [description]="'docs.floatButton.import' | translate" />
                <hrm-float-button [icon]="fileExport" [description]="'docs.floatButton.export' | translate" />
              </hrm-float-button-group>
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.floatButton.exBadgeT' | translate"
          [desc]="'docs.floatButton.exBadgeD' | translate">
          <sg-row [label]="'docs.floatButton.rowBadge' | translate">
            <div class="fb-screen">
              <hrm-float-button [icon]="messageCircle" [badge]="{ nzCount: 5 }" />
            </div>
            <div class="fb-screen">
              <hrm-float-button [icon]="bell" [badge]="{ nzDot: true }" />
            </div>
            <div class="fb-screen">
              <hrm-float-button shape="square" [icon]="headset" [description]="'docs.floatButton.support' | translate" />
            </div>
          </sg-row>
        </sg-example>

      </div>

    </sg-doc>
  `,
  styles: [`
    /* Khung "màn hình" thu nhỏ để neo nút nổi vào góc thẻ thay vì góc trình duyệt. */
    .fb-screen {
      position: relative; width: 240px; height: 180px; flex: 0 0 auto;
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface-subtle); overflow: hidden;
    }
    .fb-screen-tall { height: 260px; }
    .fb-hint {
      position: absolute; top: 12px; left: 12px;
      font-size: var(--fs-12); color: var(--text-sub);
    }
    /* Nút nổi mặc định position:fixed (góc trình duyệt) → ép nút/cụm cấp cao nhất
       về absolute trong khung. Chỉ nhắm phần tử con trực tiếp của wrapper để không
       phá vị trí các nút con bên trong 1 nhóm (ng-zorro tự xếp tương đối). */
    .fb-screen ::ng-deep hrm-float-button > .ant-float-btn,
    .fb-screen ::ng-deep hrm-float-button-group > .ant-float-btn-group {
      position: absolute; bottom: 16px; right: 16px; inset-inline-end: 16px;
    }
  `],
})
export class SgDocFloatButton {
  protected readonly plus = IconPlus;
  protected readonly arrowUp = IconArrowUp;
  protected readonly userPlus = IconUserPlus;
  protected readonly fileImport = IconFileImport;
  protected readonly fileExport = IconFileExport;
  protected readonly messageCircle = IconMessageCircle;
  protected readonly headset = IconHeadset;
  protected readonly bell = IconBell;
  protected readonly when = [
    'docs.floatButton.when1',
    'docs.floatButton.when2',
    'docs.floatButton.when3',
  ];
}
