import { Component, input, output } from '@angular/core';
import { NzFloatButtonModule, NzFloatButtonBadge } from 'ng-zorro-antd/float-button';
import { NzFourDirectionType } from 'ng-zorro-antd/core/types';
import { TablerIconComponent } from '@tabler/icons-angular';

export type HrmFloatButtonType = 'default' | 'primary';
export type HrmFloatButtonShape = 'circle' | 'square';
/** Cấu hình badge (huy hiệu) trên nút nổi — số/chấm, mọi field tùy chọn. */
export type HrmFloatButtonBadge = NzFloatButtonBadge;

/** hrm-float-button — nút nổi cố định góc màn hình, bọc nz-float-button.
 *  Biểu tượng dùng Tabler object mode (qua ng-template → nzIcon):
 *  <hrm-float-button [icon]="IconPlus" type="primary" description="Thêm" />
 *  Đặt trong <hrm-float-button-group> để gom nhiều hành động vào 1 cụm. */
@Component({
  selector: 'hrm-float-button',
  imports: [NzFloatButtonModule, TablerIconComponent],
  template: `
    <nz-float-button
      [nzType]="type()"
      [nzIcon]="icon() ? iconTpl : null"
      [nzDescription]="description() || null"
      [nzShape]="shape()"
      [nzBadge]="badge()"
      [nzHref]="href() || null"
      (nzOnClick)="click.emit()"></nz-float-button>
    <ng-template #iconTpl><tabler-icon [icon]="$any(icon())" [size]="18" /></ng-template>
  `,
  host: { class: 'hrm-float-button' },
})
export class HrmFloatButton {
  readonly type = input<HrmFloatButtonType>('default');
  /** Biểu tượng Tabler (object mode). VD: [icon]="IconPlus". */
  readonly icon = input<unknown>(null);
  readonly description = input('');
  readonly shape = input<HrmFloatButtonShape>('circle');
  /** Huy hiệu số/chấm góc nút. VD: [badge]="{ nzCount: 5 }" hoặc [badge]="{ nzDot: true }". */
  readonly badge = input<HrmFloatButtonBadge | null>(null);
  readonly href = input('');
  readonly click = output<void>();
}

/** hrm-float-button-group — gom nhiều hrm-float-button thành 1 cụm mở rộng,
 *  bọc nz-float-button-group. Nút cha hiện icon; bấm/di chuột để bung các nút con.
 *  <hrm-float-button-group [icon]="IconPlus"> <hrm-float-button ... /> </hrm-float-button-group> */
@Component({
  selector: 'hrm-float-button-group',
  imports: [NzFloatButtonModule, TablerIconComponent],
  template: `
    <nz-float-button-group
      [nzType]="type()"
      [nzIcon]="icon() ? iconTpl : null"
      [nzShape]="shape()"
      [nzTrigger]="trigger()"
      [nzPlacement]="placement()"
      (nzOnOpenChange)="openChange.emit($event)">
      <ng-content />
    </nz-float-button-group>
    <ng-template #iconTpl><tabler-icon [icon]="$any(icon())" [size]="18" /></ng-template>
  `,
  host: { class: 'hrm-float-button-group' },
})
export class HrmFloatButtonGroup {
  readonly type = input<HrmFloatButtonType>('default');
  /** Biểu tượng Tabler (object mode) cho nút cha khi đóng. */
  readonly icon = input<unknown>(null);
  readonly shape = input<HrmFloatButtonShape>('circle');
  /** Cách bung cụm: bấm hoặc di chuột. */
  readonly trigger = input<'click' | 'hover'>('click');
  /** Hướng bung các nút con quanh nút cha. */
  readonly placement = input<NzFourDirectionType>('top');
  readonly openChange = output<boolean>();
}
